#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# Cirrus Function URL rejects query keys outside A-Z a-z 0-9 _ . - (EVT-412)
for f in app/forms/*.form; do
  form=$(basename "$f" .form)
  bash bin/render "$form" | grep -o 'action="[^"]*"' | while read -r a; do
    u=${a#action=\"}; u=${u%\"}; q=${u#*\?}; k=${q%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $k"; exit 1; }
  done || fail=1
done
for a in save publish refund assign; do
  u=$(bash -c '. lib/actions.sh; action_url "$1"' _ "$a")
  bash bin/handle POST "/events/1/edit$u" | grep -q "^200 $a\$" || { echo "handle $a"; fail=1; }
done
exit $fail

