#!/bin/bash
fail=0
bash bin/render event | grep -q 'action="?action=save"' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# Cirrus Function URL accepts only A-Z a-z 0-9 _ . - in query keys (docs/platform/cirrus-functions.md)
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="?//; s/"$//; s/=.*//' | grep -qvE '^[A-Za-z0-9_.-]+$' && { echo "bad key in $f"; fail=1; }
